      G.TIN_MAY = { nguong: 10, so: { 'N-XONG:T1': 34 }, duoiNguong: ['N-TANG:T5'], chuyenDaChon: 3 };
      const dat = G.tinSo('N-XONG', 999, 'T1');
      const duoi = G.tinSo('N-TANG', 999, 'T5');
