      r.saoTheoTang = G.bkSao('T1') === 1 && G.bkSao('T3') === 3 && G.bkSao('T5') === 5;
      const tt3 = G.HT_TANG.filter(x => x.ma === 'T3')[0], luuSo = tt3.so;
